/**
 * Sync physics state to a Three.js object with interpolation.
 *
 * Works for all body types (dynamic, kinematic) that have position/quaternion
 * and their previous frame values (prevPosition*, prevQuaternion*).
 *
 * @param {Object} state - Physics body state (from physics.player, getKinematicBody, etc.)
 * @param {THREE.Object3D} mesh - Target Three.js object to sync position/quaternion to
 * @param {number} alpha - Interpolation factor (0-1), typically from PhysicsController.getInterpolationAlpha()
 *
 * @example
 * const alpha = physicsController.getInterpolationAlpha();
 *
 * // Dynamic body
 * syncPhysics(physics.player, playerMesh, alpha);
 *
 * // Kinematic body
 * const state = physics.getKinematicBody(index);
 * syncPhysics(state, platformMesh, alpha);
 */
export function syncPhysics(state: any, mesh: THREE.Object3D, alpha: number): void;
